VALUES ('reading-real-2023-1','reading','real','{"type":"real","meta":{"year":2023,"region":"广东"}}','2023年真题·阅读理解 Passage 1',2,'["主旨大意","细节理解"]','{"id":"reading-real-2023-1","type":"reading","source":{"type":"real","meta":{"year":2023,"region":"广东"}},"passage":"Digital reading is changing how college students study. Instead of carrying heavy textbooks, many students now read on tablets and phones. Researchers found that students who read digitally tend to scan quickly but remember less. Meanwhile, those who read paper books take slower notes and score higher in comprehension tests.","questions":[{"id":1,"stem":"What is the main idea of the passage?","options":[{"key":"A","text":"Digital reading improves memory."},{"key":"B","text":"Reading habits affect learning results."},{"key":"C","text":"Paper textbooks are too expensive."},{"key":"D","text":"College students never read paper books."}]},{"id":2,"stem":"According to the passage, digital readers tend to ________.","options":[{"key":"A","text":"read slowly and carefully"},{"key":"B","text":"take detailed notes"},{"key":"C","text":"scan quickly and remember less"},{"key":"D","text":"score higher in tests"}]},{"id":3,"stem":"Who scores higher in comprehension tests?","options":[{"key":"A","text":"Digital readers."},{"key":"B","text":"Paper book readers."},{"key":"C","text":"Teachers."},{"key":"D","text":"Tablet sellers."}]},{"id":4,"stem":"The word “scan” in the passage most probably means ________.","options":[{"key":"A","text":"to copy a document"},{"key":"B","text":"to read quickly"},{"key":"C","text":"to take photos"},{"key":"D","text":"to write neatly"}]},{"id":5,"stem":"What can be inferred from the passage?","options":[{"key":"A","text":"Students should give up digital devices."},{"key":"B","text":"Paper reading may help deeper learning."},{"key":"C","text":"Tablets are useless for study."},{"key":"D","text":"Notes are unnecessary in tests."}]}]}','{"questions":[{"id":1,"answer":"B","explanation":"全文对比数字阅读与纸质阅读对学习结果的影响,故选 B。"},{"id":2,"answer":"C","explanation":"第二句明确指出数字阅读者 tend to scan quickly but remember less。"},{"id":3,"answer":"B","explanation":"第三句说明纸质书阅读者 score higher in comprehension tests。"},{"id":4,"answer":"B","explanation":"scan 与 remember less 并列,结合语境意为“快速浏览”。"},{"id":5,"answer":"B","explanation":"由纸质阅读者记得更牢、得分更高可推出纸质阅读有助于深度学习。"}]}',1,10.0,2.0,1) AS new
