VALUES ('reading-teacher-1','reading','teacher','{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}}','王老师·模拟阅读卷 Passage 1',3,'["主旨大意","推理判断"]','{"id":"reading-teacher-1","type":"reading","source":{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}},"passage":"Sleep is often the first thing college students give up before exams. However, research shows that an all-night study session actually harms memory. During deep sleep, the brain organizes new information and connects it with what we already know. Students who sleep seven to eight hours usually perform better.","questions":[{"id":1,"stem":"What do many students give up before exams?","options":[{"key":"A","text":"Breakfast."},{"key":"B","text":"Sleep."},{"key":"C","text":"Sports."},{"key":"D","text":"Friends."}]},{"id":2,"stem":"How does an all-night study session affect memory?","options":[{"key":"A","text":"It improves memory greatly."},{"key":"B","text":"It harms memory."},{"key":"C","text":"It has no effect."},{"key":"D","text":"It cleans the brain."}]},{"id":3,"stem":"What does the brain do during deep sleep?","options":[{"key":"A","text":"It stops working completely."},{"key":"B","text":"It organizes new information."},{"key":"C","text":"It only dreams."},{"key":"D","text":"It forgets old knowledge."}]},{"id":4,"stem":"Students who sleep 7-8 hours usually ________.","options":[{"key":"A","text":"perform better"},{"key":"B","text":"feel hungrier"},{"key":"C","text":"wake up late"},{"key":"D","text":"miss classes"}]},{"id":5,"stem":"What can we learn from the passage?","options":[{"key":"A","text":"Staying up all night is wise before exams."},{"key":"B","text":"Enough sleep supports exam performance."},{"key":"C","text":"Memory has nothing to do with sleep."},{"key":"D","text":"Students do not need rest."}]}]}','{"questions":[{"id":1,"answer":"B","explanation":"第一句指出睡眠是学生考前最先放弃的东西。"},{"id":2,"answer":"B","explanation":"第二句 says an all-night study session actually harms memory。"},{"id":3,"answer":"B","explanation":"第三句说明深睡眠时大脑整理新信息并与旧知识连接。"},{"id":4,"answer":"A","explanation":"末句明确指出睡眠充足的考生通常表现得更好。"},{"id":5,"answer":"B","explanation":"全文论证充足睡眠有助于记忆与考试发挥。"}]}',1,10.0,2.0,1) AS new
