VALUES ('matching-real-2023-1','matching','real','{"type":"real","meta":{"year":2023,"region":"广东"}}','2023年真题·五选五 Passage 1',3,'["句间衔接","逻辑顺序"]','{"id":"matching-real-2023-1","type":"matching","source":{"type":"real","meta":{"year":2023,"region":"广东"}},"passage":"Reading is one of the most valuable habits a student can build. [[1]] First, set a fixed time every day. [[2]] Second, choose materials at the right level. [[3]] Third, keep a small notebook for new words. [[4]] Finally, share what you read with friends. [[5]]","blanks":[{"id":1},{"id":2},{"id":3},{"id":4},{"id":5}],"options":[{"key":"A","text":"A regular time helps your brain get ready to focus."},{"key":"B","text":"Reviewing these words once a week keeps them fresh."},{"key":"C","text":"How can you build this habit? Here are four tips."},{"key":"D","text":"Talking about a book makes its ideas truly yours."},{"key":"E","text":"If a text is too hard, you may give up too soon."}]}','{"blanks":[{"id":1,"answer":"C","explanation":"本空引出后文的 First/Second 建议,需选择承上启下的总起句。"},{"id":2,"answer":"A","explanation":"A 解释固定时间的好处,承接 First, set a fixed time。"},{"id":3,"answer":"E","explanation":"E 说明材料太难的后果,呼应 choose materials at the right level。"},{"id":4,"answer":"B","explanation":"B 讲述记录生词如何帮助记忆,承接 keep a notebook。"},{"id":5,"answer":"D","explanation":"D 收束全段,鼓励坚持并点明坚持带来的变化,与分享话题衔接。"}]}',1,10.0,2.0,1) AS new
ON DUPLICATE KEY UPDATE `type`=new.`type`,`source_type`=new.`source_type`,`source_meta`=new.`source_meta`,`title`=new.`title`,`difficulty`=new.`difficulty`,`tags`=new.`tags`,`content`=new.`content`,`answer_key`=new.`answer_key`,`has_answer`=new.`has_answer`,`total_score`=new.`total_score`,`per_question_score`=new.`per_question_score`,`status`=new.`status`;

