VALUES ('matching-teacher-1','matching','teacher','{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}}','王老师·模拟五选五 Passage 1',4,'["句间衔接","因果逻辑"]','{"id":"matching-teacher-1","type":"matching","source":{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}},"passage":"Morning exercise can change your whole day. [[1]] First, ten minutes of stretching wakes up your muscles. [[2]] Second, exercise releases chemicals that lift your mood. [[3]] Third, a short run improves blood flow to the brain. [[4]] You do not need a gym membership to enjoy these benefits. [[5]]","blanks":[{"id":1},{"id":2},{"id":3},{"id":4},{"id":5}],"options":[{"key":"A","text":"As a result, you think more clearly in morning classes."},{"key":"B","text":"Here are three reasons to give it a try."},{"key":"C","text":"A jump rope or a simple mat is enough to start."},{"key":"D","text":"Your body feels lighter and more flexible after that."},{"key":"E","text":"With a better mood, you learn faster."}]}','{"blanks":[{"id":1,"answer":"B","explanation":"空后展开三点好处,需总起句引出。"},{"id":2,"answer":"D","explanation":"D 具体说明拉伸后身体变灵活,承接 wakes up your muscles。"},{"id":3,"answer":"E","explanation":"E 指出好心情对学习状态的影响,承接 lift your mood。"},{"id":4,"answer":"A","explanation":"A 承接 blood flow,解释大脑清醒的表现。"},{"id":5,"answer":"C","explanation":"C 提出在家即可运动,呼应 no gym membership。"}]}',1,10.0,2.0,1) AS new
