INSERT INTO `question` (`id`,`type`,`source_type`,`source_meta`,`title`,`difficulty`,`tags`,`content`,`answer_key`,`has_answer`,`total_score`,`per_question_score`,`status`)
VALUES ('grammar-teacher-1','grammar-fill','teacher','{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}}','王老师·模拟语法填空 Passage 1',3,'["时态语态","比较结构"]','{"id":"grammar-teacher-1","type":"grammar-fill","source":{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}},"passage":"More and more college students are choosing part-time jobs, not only for money but also for experience. Working in a coffee shop, for example, helps students become more [[1]] (confidence) when talking to strangers. A study found that students with working experience tend to be better at [[2]] (manage) their time. However, experts warn that study should always come [[3]] (one). They suggest students limit work to ten hours a week. Otherwise, grades may drop [[4]] (quick), and tiredness will follow. “A part-time job is like seasoning,” one career adviser said, “too much of it [[5]] (ruin) the dish.” She advises students [[6]] (choose) jobs related to their majors, so that the work also builds future careers. Many campuses now hold job fairs for students [[7]] want to gain real-world skills. With [[8]] (they) help, hundreds of students have found suitable positions. Those who balance work and study well often say the experience makes them [[9]] (responsible) than before. In the end, the value of a part-time job depends on how wisely it [[10]] (use).","blanks":[{"id":1,"hint":"confidence"},{"id":2,"hint":"manage"},{"id":3,"hint":"one"},{"id":4,"hint":"quick"},{"id":5,"hint":"ruin"},{"id":6,"hint":"choose"},{"id":7},{"id":8,"hint":"they"},{"id":9,"hint":"responsible"},{"id":10,"hint":"use"}]}','{"blanks":[{"id":1,"answer":"confident","acceptAlternatives":null,"explanation":"become + 形容词,自信的 confident。"},{"id":2,"answer":"managing","acceptAlternatives":null,"explanation":"be good at doing sth. 擅长做某事,at 后接动名词。"},{"id":3,"answer":"first","acceptAlternatives":null,"explanation":"come first 位居第一,固定表达。"},{"id":4,"answer":"quickly","acceptAlternatives":null,"explanation":"修饰动词 drop 需用副词 quickly。"},{"id":5,"answer":"ruins","acceptAlternatives":null,"explanation":"引用格言用一般现在时,主语 too much of it 视为单数。"},{"id":6,"answer":"to choose","acceptAlternatives":null,"explanation":"advise sb. to do sth. 建议某人做某事。"},{"id":7,"answer":"who","acceptAlternatives":null,"explanation":"定语从句先行词 students 指人,从句缺主语,用 who。"},{"id":8,"answer":"their","acceptAlternatives":null,"explanation":"with + 形代 + 名词,their help 他们的帮助。"},{"id":9,"answer":"more responsible","acceptAlternatives":null,"explanation":"than before 表比较,多音节词前加 more。"},{"id":10,"answer":"is used","acceptAlternatives":null,"explanation":"it(job)与 use 为被动关系,陈述客观事实用一般现在时被动。"}]}',1,15.0,1.5,1) AS new
ON DUPLICATE KEY UPDATE `type`=new.`type`,`source_type`=new.`source_type`,`source_meta`=new.`source_meta`,`title`=new.`title`,`difficulty`=new.`difficulty`,`tags`=new.`tags`,`content`=new.`content`,`answer_key`=new.`answer_key`,`has_answer`=new.`has_answer`,`total_score`=new.`total_score`,`per_question_score`=new.`per_question_score`,`status`=new.`status`;

INSERT INTO `question` (`id`,`type`,`source_type`,`source_meta`,`title`,`difficulty`,`tags`,`content`,`answer_key`,`has_answer`,`total_score`,`per_question_score`,`status`)
VALUES ('writing-real-2023-1','writing','real','{"type":"real","meta":{"year":2023,"region":"广东"}}','2023年真题·写作',4,'["书信写作","建议信"]','{"id":"writing-real-2023-1","type":"writing","source":{"type":"real","meta":{"year":2023,"region":"广东"}},"prompt":"假定你是李华,你的英国笔友 Peter 计划来中国学习,写信向你咨询如何适应中国的校园生活。请给他写一封回信。","requirements":["内容须包含三点建议(如语言交流、社团活动、饮食习惯等);","书信格式完整(称呼、正文、结束语、署名);","可适当增加细节,使行文连贯。"],"wordLimit":120,"scoringDimensions":["内容要点","语言表达","篇章结构","格式规范"]}','{"sampleAnswer":"Dear Peter,\\n\\nI am glad to hear that you are coming to study in China. Here are three tips to help you settle in quickly.\\n\\nFirst, try to speak Chinese in daily life. Even simple greetings will help you make friends and improve your language skills. Second, join a student club, such as a basketball team or a calligraphy group, where you can meet people who share your interests. Third, give yourself time to get used to the food. Many canteens offer both Chinese and Western dishes, so you will always find something you like.\\n\\nI hope these suggestions are helpful. Looking forward to seeing you soon!\\n\\nYours sincerely,\\nLi Hua"}',0,15.0,15.0,1) AS new
ON DUPLICATE KEY UPDATE `type`=new.`type`,`source_type`=new.`source_type`,`source_meta`=new.`source_meta`,`title`=new.`title`,`difficulty`=new.`difficulty`,`tags`=new.`tags`,`content`=new.`content`,`answer_key`=new.`answer_key`,`has_answer`=new.`has_answer`,`total_score`=new.`total_score`,`per_question_score`=new.`per_question_score`,`status`=new.`status`;

INSERT INTO `question` (`id`,`type`,`source_type`,`source_meta`,`title`,`difficulty`,`tags`,`content`,`answer_key`,`has_answer`,`total_score`,`per_question_score`,`status`)
VALUES ('writing-teacher-1','writing','teacher','{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}}','王老师·模拟写作 1',4,'["议论文","观点对比"]','{"id":"writing-teacher-1","type":"writing","source":{"type":"teacher","meta":{"teacherName":"王老师","school":"启航班工作室"}},"prompt":"现在越来越多的大学生选择在毕业前考取各种职业证书。有人认为这有助于就业,也有人认为会耽误学业。请就此话题写一篇短文,陈述你的观点。","requirements":["词数 100-120;","必须有明确的个人观点;","至少给出两条支撑理由。"],"wordLimit":120,"scoringDimensions":["内容要点","语言表达","篇章结构","格式规范"]}','{"sampleAnswer":"More and more college students are taking professional certificates before graduation. In my opinion, the advantages outweigh the disadvantages.\\n\\nFirst, certificates show employers that a student has practical skills beyond textbooks, which helps in job hunting. Second, preparing for a certificate exam forces students to manage their time well and keep learning. As long as students do not let certificates replace their major courses, the process is rewarding.\\n\\nOf course, students should choose certificates related to their career plans instead of collecting random ones. With a clear goal and balanced effort, certificates can open more doors after graduation."}',0,15.0,15.0,1) AS new
ON DUPLICATE KEY UPDATE `type`=new.`type`,`source_type`=new.`source_type`,`source_meta`=new.`source_meta`,`title`=new.`title`,`difficulty`=new.`difficulty`,`tags`=new.`tags`,`content`=new.`content`,`answer_key`=new.`answer_key`,`has_answer`=new.`has_answer`,`total_score`=new.`total_score`,`per_question_score`=new.`per_question_score`,`status`=new.`status`;

